import{a as e,i as t,r as n,t as r}from"./app-BSn6oFAa.js";var i=JSON.parse(`{"path":"/","title":"首页","lang":"zh-CN","frontmatter":{"home":true,"title":"首页","heroText":"Namachokoretomusu","tagline":"QQ 机器人指令文档","actions":[{"text":"指令指南","link":"/guide/checkin","type":"primary"}]},"git":{},"filePathRelative":"README.md"}`),a={name:`README.md`};function o(r,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[t(`<h2 id="关于" tabindex="-1"><a class="header-anchor" href="#关于"><span>关于</span></a></h2><p>Namachokoretomusu 是一个 QQ 群聊机器人，提供签到、街机厅人数查询、商店、情侣关系等多种功能。</p><h2 id="快速开始" tabindex="-1"><a class="header-anchor" href="#快速开始"><span>快速开始</span></a></h2><p>绝大多数功能都需要以 <code>.</code> 开头，参数之间使用空格分隔。</p><h3 id="使用规则" tabindex="-1"><a class="header-anchor" href="#使用规则"><span>使用规则</span></a></h3><ul><li>常规指令格式：<code>.指令 参数1 参数2</code>；不识别的指令不会回复。</li><li>参数含空格时可用中文引号包裹，例如 <code>.谱面预览 &quot;Shiny Smily Story&quot; ex</code>。</li><li><code>帮助</code> / <code>Help</code> / <code>help</code> 和单独发送 <code>雪希</code> / <code>Yuki</code>（大小写不敏感）支持<strong>不加前缀</strong>触发；单独 @ 机器人且不附带文本时也会触发呼叫回复。</li><li>群数据类功能（地点别名、人数上报、语录、每日老婆和 NTR 统计）会按群隔离；语录功能仅限群聊。</li></ul><h3 id="常用指令" tabindex="-1"><a class="header-anchor" href="#常用指令"><span>常用指令</span></a></h3><table><thead><tr><th>指令</th><th>说明</th></tr></thead><tbody><tr><td><code>帮助</code> / <code>雪希</code></td><td>帮助页 / 呼叫机器人（支持无前缀）</td></tr><tr><td><code>.签到</code></td><td>每日签到，获取经验和金币</td></tr><tr><td><code>.jk</code></td><td>查看街机厅人数</td></tr><tr><td><code>.商店</code></td><td>查看可购买物品</td></tr><tr><td><code>.反馈 内容</code></td><td>提交反馈</td></tr><tr><td><code>.看图</code></td><td>获取随机图片</td></tr><tr><td><code>.随机语录</code></td><td>随机展示一条本群语录</td></tr><tr><td><code>.成员 时乃空</code></td><td>查询 Hololive 成员资料</td></tr><tr><td><code>.查歌 初音</code></td><td>搜索舞萌 DX 歌曲</td></tr></tbody></table><div class="hint-container tip"><p class="hint-container-title">提示</p><p>需要 @ 用户的指令必须使用 QQ 群中的实际艾特消息，不能只输入普通文本。</p></div>`,9)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};